/**
 * Unit tests for MultiplePiePlot.setPieChart.
 */
public class MultiplePiePlot_setPieChart_TriageGen1Test {

    private MultiplePiePlot multiplePiePlot;

    @Before
    public void setUp() {
        multiplePiePlot = new MultiplePiePlot();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_NullArgument() {
        multiplePiePlot.setPieChart(null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSetPieChart_WrongPlotType() {
        // Create a chart that is not a PieChart (e.g., a BarChart)
        // Since we don't have easy access to other factories here, 
        // we can mock or use a standard JFreeChart that has a different plot type.
        // For the purpose of this test, we simulate a JFreeChart with a non-PiePlot.
        JFreeChart nonPieChart = new JFreeChart("Non-Pie Chart", null, null, false);
        // Note: In real JFreeChart, the plot is set via constructor or setter.
        // If the default plot is null or not PiePlot, it should trigger the exception.
        multiplePiePlot.setPieChart(nonPieChart);
    }

    @Test
    public void testSetPieChart_ValidPieChart() {
        // Create a valid PieChart
        DefaultPieDataset dataset = new DefaultPieDataset();
        dataset.setValue("A", 10.0);
        dataset.setValue("B", 20.0);
        JFreeChart pieChart = JFreeChartFactory.createPieChart("Test Pie Chart", dataset, true, true, false);

        // Verify the chart is indeed a PieChart (contains PiePlot)
        assertNotNull(pieChart.getPlot());
        assertEquals(true, pieChart.getPlot() instanceof PiePlot);

        // Execute the method under test
        multiplePiePlot.setPieChart(pieChart);

        // Verify the result
        assertEquals(pieChart, multiplePiePlot.getPieChart());
    }
}
